INSERT INTO `attempts` VALUES ('03d6636c-35f7-495d-83e8-5a017841623b','f924e8c4-b4ac-41bc-93c4-3642791d5325',6,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"以这张夜晚庭院灯笼照片为基础优化,不改变主体位置和纵向构图。保留中式木栅栏、树干与两盏暖黄色灯笼,强化静谧、温暖、略带孤独感的电影夜景氛围；加入轻薄夜雾、潮湿地面的微弱反光、少量细雨或空气微尘,让灯光自然扩散。整体采用低饱和暖棕与墨黑色调,暗部有细节\\n画面干净克制,去除底部水印和文字。\",\"references\":[\"路灯.jpg\"],\"tags_prompt\":[{\"tag_name\":\"构图方式\",\"tag_value\":\"保留夜晚庭院木栅栏、树干与双灯笼路灯的纵向构图，灯笼作为视觉焦点，画面更干净有层次\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"深邃暗部，暖金色灯光柔和扩散，细微光晕与薄雾，明暗对比克制，营造安静的夜游感\"},{\"tag_name\":\"环境动态\",\"tag_value\":\"加入若隐若现的树叶、潮湿石板路反光、少量漂浮微尘或细雨，远处保留朦胧灯火\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"电影感夜景摄影，低饱和暖棕与墨黑色调，细腻暗部层次，自然胶片颗粒，高级且真实\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"去除底部水印与无关文字，避免过曝灯泡、杂乱背景、过度 HDR、塑料感和不自然锐化\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/03/155854_78bf52402a224d92baa626e7d16d9243.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','6751b4849af74569ae08193560d23b4a',NULL,NULL,NULL,'2026-09-03 15:57:33.775','2026-09-03 15:57:43.531','2026-09-03 15:58:56.538','2026-09-03 15:58:56.540');
INSERT INTO `attempts` VALUES ('066876f5-39d1-4f1f-ae77-0dacfaf31044','430d7679-1ecb-4600-8914-3d209cbf92fb',4,'succeeded','将参考图像中的主体，转化为一幅可爱、古怪的手绘涂鸦插画。\r\n\r\n采用极简的儿童故事书 / 时装速写美学，使用松散、不完美的黑色墨水线条，可见的铅笔涂鸦笔触，细微的交叉排线，以及迷人的手工质感。在保持参考图像中人物可识别的面部特征、发型、脸型、服饰、配饰和整体身份的同时，将它们简化成一个可爱的插图角色。\r\n\r\n角色设计：\r\n\r\n大脑袋和简化的小身体\r\n\r\n简单的点状眼睛和极小的嘴巴\r\n\r\n柔和圆润的面部特征\r\n\r\n脸颊上淡淡的粉红色红晕\r\n\r\n凌乱、富有表现力的手绘头发，带有许多松散的素描线\r\n\r\n略微夸张、好玩的形体比例\r\n\r\n自然放松的姿势，带有奇思妙想的时装插画感\r\n\r\n艺术风格：\r\n\r\n黑白铅笔 / 墨水涂鸦\r\n\r\n粗糙、不完美的素描线，而非干净的数字描边\r\n\r\n密集的涂鸦式头发和衣物细节\r\n\r\n浅淡的手绘色彩点缀\r\n\r\n微妙的水彩 / 蜡笔质感上色\r\n\r\n极简的明暗处理\r\n\r\n白色或米白色干净背景\r\n\r\n大量留白\r\n\r\n可爱、天真、俏皮、舒适的美学\r\n\r\n看起来像原创的手工笔记本 / 时尚涂鸦插画\r\n\r\n保留参考图像中的重要细节，同时将所有内容转化为一致的涂鸦风格。最终图像应呈现手绘感、略显不完美、讨喜、富有表现力且毫不费力的时尚感，而不是精致的矢量图或3D卡通。','gpt-image-2','1024x1024','medium','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/08/30/211432_d3f79cd13cf3493d8971c87e7f527ed0.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','ad278daada7d4098957f9b1af5e8cf86',NULL,NULL,NULL,'2026-08-30 21:13:42.022',NULL,NULL,'2026-08-30 21:14:34.557');
INSERT INTO `attempts` VALUES ('0c883c7d-87d5-4ff8-85a7-0d253c01459a','94f1341e-9a08-4832-bd51-30c6dd5525b3',1,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"[任务模型.png]保持人物模型不变,然后丰富任务的动作与表情,摆一个炫酷的POSE\",\"references\":[\"任务模型.png\"],\"tags_prompt\":[{\"tag_name\":\"外观特征\",\"tag_value\":\"沿用原图人物的全部外貌、发型与服饰细节，保持一致性\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"表情自信、专注，可能带有挑衅或玩味的微表情，增加人物张力\"},{\"tag_name\":\"动作姿态\",\"tag_value\":\"身体重心后倾，一条腿微微抬起，手臂做出有张力的造型，如单手插兜或指向镜头，形成动态平衡的帅气姿势\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"极简室内空间\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"纯净的抹茶绿的背景，无杂乱元素，突出人物主体\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"炫酷、自信、带有街头或现代感的酷炫氛围\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高清画质，人物动作与表情细节清晰，动态模糊控制得当\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/220254_bb85f6521fbe45e0accac3bd79e72e7b.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','8bb3f29d8db9444aa92835a43fdb362c',NULL,NULL,NULL,'2026-09-07 22:01:51.878','2026-09-07 22:01:51.913','2026-09-07 22:02:55.218','2026-09-07 22:02:55.219');
INSERT INTO `attempts` VALUES ('118128bd-faa5-4e1d-a440-392272818bd3','fa8f3af9-0c43-4e48-98d5-202856b8e52d',2,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"为长沙创作一幅温暖、友好的编辑式旅行插画。强调至少要有[橘子洲头.png]和[天心阁.png]\",\"references\":[\"橘子洲头.png\",\"天心阁.png\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"长沙的地标建筑、特色街景、当地交通、自然景观、植物、动物、美食与文化物件\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"各元素自然组合并适度重叠，保持疏朗通透\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"平衡的编辑式构图，类似旅行手账或设计师速写本\"},{\"tag_name\":\"主体位置\",\"tag_value\":\"主体元素分散布局，避免集中堆叠\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"大面积留白，每个元素保持呼吸感\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"长沙\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简洁留白背景，不绘制复杂城市全景\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"手绘旅行手账、精品旅行指南、当代杂志插画\"},{\"tag_name\":\"参考流派\",\"tag_value\":\"编辑式旅行插画、极简涂鸦\"},{\"tag_name\":\"媒介形式\",\"tag_value\":\"黑色毡尖笔\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"扁平化绘制，简化形状，极少内部细节\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"线条略微摇晃，粗细自然变化，松弛随性，保留手绘瑕疵\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"黑白为主\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"仅使用一种强调色 黑色\"},{\"tag_name\":\"色彩饱和度\",\"tag_value\":\"强调色低面积、克制使用\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"平面照明，无渐变与高光\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"温暖、友好、轻松、俏皮、简约、优雅\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"强调 长沙最具辨识度的文化与地域特征；线条自然断开、偶有重叠，体现手工绘制的不完美；强调色仅用于水面、天空、窗户、招牌、服饰点缀、装饰高光或少量建筑细节\"},{\"tag_name\":\"负面元素\",\"tag_value\":\"避免写实城市景观、照片感、3D效果、渐变、厚重阴影、油画笔触、复杂纹理、金属光泽、机械精确轮廓、矢量风格、过度细节、拥挤构图、额外颜色\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"干净、通透、平面化、图形感强，突出手工毡尖笔涂鸦质感\"}]}','gpt-image-2','auto','auto','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/02/112210_fc2dddedca974520826f6a9cda8d0eac.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','f572982e6bc947218e3dfd3dc2c762ed',NULL,NULL,NULL,'2026-09-02 11:21:00.300',NULL,NULL,'2026-09-02 11:29:55.098');
INSERT INTO `attempts` VALUES ('1dcfadb1-3a18-4a4b-acda-00ccb5ca5f7f','7271d4a0-2bdd-4b34-909a-4dc0817dbd89',1,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"把人物[人物.jpg]做成[样例.png]的风格的3D卡通图,人物上半身要全部展示出,然后需要做成9宫格形式的那种图,每个格子展示出不同的角度,方便后续建模\",\"references\":[\"样例.png\",\"人物.jpg\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"人物\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"单人\"},{\"tag_name\":\"外观特征\",\"tag_value\":\"3D卡通风格的人物，上半身全部展示\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"9宫格网格布局，每个格子展示人物不同角度\"},{\"tag_name\":\"景别范围\",\"tag_value\":\"上半身特写\"},{\"tag_name\":\"拍摄视角\",\"tag_value\":\"多种固定角度，包括正面、侧面、背面等，以提供全面视角\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"3D卡通渲染风格\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高清晰度，角度分明，无遮挡，适合后续3D建模参考\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"确保人物上半身在每个格子中完整且角度各异\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/204443_6aca562764904cf3b2a61de89901bd5d.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','bfc449d1eb734d8c9360368ea850c79b',NULL,NULL,NULL,'2026-09-07 20:44:07.138','2026-09-07 20:44:07.177','2026-09-07 20:44:45.001','2026-09-07 20:44:45.001');
INSERT INTO `attempts` VALUES ('1e94f256-1b1b-4747-ac32-57cb73cf90e6','eabcc7c4-1c2e-4339-94e7-2ff3d0e035f7',2,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"[玫瑰礼堂.jpg]原图在上面,AI生成的部分在下面,浪漫风格,不要具象,使用抽象风格,然后颜色选取需要情感色彩强烈，蓝色，黑色与红色等等；,浓墨触笔但又要具有简约的感觉\",\"references\":[\"玫瑰礼堂.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"抽象浪漫风格，不包含具象元素，强调情感表达\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"情感强烈的色调，以深蓝色、黑色和鲜艳红色为主\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"蓝色、黑色与红色交织，对比鲜明，传达深邃与激情\"},{\"tag_name\":\"色彩饱和度\",\"tag_value\":\"高饱和度，增强色彩的情感冲击力\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"浓墨触笔，粗犷而富有表现力的笔触\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"简约抽象构图，通过留白和简化形式突出情感\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"大量留白，营造简约、空灵的视觉感受\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"浪漫而情感强烈的氛围，带有深邃和内省气质\"},{\"tag_name\":\"负面元素\",\"tag_value\":\"避免任何具象、写实或清晰的物体描绘，不出现现实场景\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"抽象艺术品质，笔触流畅，色彩层次丰富，情感表达充分\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/191806_1329c01a12714bfdae11643ae647ba2a.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','dfa62d3b57f747dba87f5ed640cb118f',NULL,NULL,NULL,'2026-09-07 19:17:23.792','2026-09-07 19:17:23.834','2026-09-07 19:18:07.377','2026-09-07 19:18:07.378');
INSERT INTO `attempts` VALUES ('22c1f38d-30b6-42a5-85c2-95e2b4c6ad16','7271d4a0-2bdd-4b34-909a-4dc0817dbd89',2,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"把人物[人物.jpg]做成[样例.png]的风格的3D卡通图,人物上半身要全部展示出,然后需要做成9宫格形式的那种图,每个格子展示出不同的角度,方便后续建模,衣服需要换成格子衬衫\",\"references\":[\"样例.png\",\"人物.jpg\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"人物\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"单人\"},{\"tag_name\":\"外观特征\",\"tag_value\":\"人物上半身全部展示，无遮挡\"},{\"tag_name\":\"服饰配件\",\"tag_value\":\"穿着格子衬衫\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"9宫格布局，每个格子展示人物不同角度\"},{\"tag_name\":\"景别范围\",\"tag_value\":\"上半身展示，半身景\"},{\"tag_name\":\"拍摄视角\",\"tag_value\":\"多视角，包括正面、侧面、背面、斜角等，用于建模参考\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"3D卡通风格，参考样例.png的艺术风格\"},{\"tag_name\":\"媒介形式\",\"tag_value\":\"3D卡通渲染\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"人物结构清晰，细节丰富，适合后续3D建模\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高质量图像，色彩鲜明，线条平滑\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/205003_d21363871cae4f8f83bfbdf7cc2dbcb3.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','dfb30f0be4d54b06ba1c9cc9c0fb0c61',NULL,NULL,NULL,'2026-09-07 20:49:08.307','2026-09-07 20:49:08.340','2026-09-07 20:50:03.533','2026-09-07 20:50:03.533');
INSERT INTO `attempts` VALUES ('2b4e4aff-dd6a-4a8b-8db0-2214494d7c95','fa8f3af9-0c43-4e48-98d5-202856b8e52d',3,'failed','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"为长沙创作一幅温暖、友好的编辑式旅行插画。强调至少要有[橘子洲头.png]和[天心阁.png]\",\"references\":[\"橘子洲头.png\",\"天心阁.png\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"长沙的地标建筑、特色街景、当地交通、自然景观、植物、动物、美食与文化物件\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"各元素自然组合并适度重叠，保持疏朗通透\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"平衡的编辑式构图，类似旅行手账或设计师速写本\"},{\"tag_name\":\"主体位置\",\"tag_value\":\"主体元素分散布局，避免集中堆叠\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"大面积留白，每个元素保持呼吸感\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"长沙\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简洁留白背景，不绘制复杂城市全景\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"手绘旅行手账、精品旅行指南、当代杂志插画\"},{\"tag_name\":\"参考流派\",\"tag_value\":\"编辑式旅行插画、极简涂鸦\"},{\"tag_name\":\"媒介形式\",\"tag_value\":\"黑色毡尖笔\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"扁平化绘制，简化形状，极少内部细节\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"线条略微摇晃，粗细自然变化，松弛随性，保留手绘瑕疵\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"黑白为主\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"仅使用一种强调色 黑色\"},{\"tag_name\":\"色彩饱和度\",\"tag_value\":\"强调色低面积、克制使用\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"平面照明，无渐变与高光\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"温暖、友好、轻松、俏皮、简约、优雅\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"强调 长沙最具辨识度的文化与地域特征；线条自然断开、偶有重叠，体现手工绘制的不完美；强调色仅用于水面、天空、窗户、招牌、服饰点缀、装饰高光或少量建筑细节\"},{\"tag_name\":\"负面元素\",\"tag_value\":\"避免写实城市景观、照片感、3D效果、渐变、厚重阴影、油画笔触、复杂纹理、金属光泽、机械精确轮廓、矢量风格、过度细节、拥挤构图、额外颜色\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"干净、通透、平面化、图形感强，突出手工毡尖笔涂鸦质感\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[]','191d80dbbb954b39ae442882e3ebc6e8',NULL,'Request timed out.',NULL,'2026-09-02 11:29:37.022','2026-09-02 11:29:42.155','2026-09-02 11:29:55.109','2026-09-02 11:29:55.110');
INSERT INTO `attempts` VALUES ('2bd719ad-6ecf-42cc-b48a-d506df7c227a','94f1341e-9a08-4832-bd51-30c6dd5525b3',3,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"[任务模型.png]保持人物模型不变,然后丰富任务的动作与表情,然后是一个打游戏时的动作\",\"references\":[\"任务模型.png\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"一个年轻男性或女性游戏玩家\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"单人\"},{\"tag_name\":\"外观特征\",\"tag_value\":\"保持原有人物模型的外观，穿着休闲服装，如T恤和牛仔裤\"},{\"tag_name\":\"服饰配件\",\"tag_value\":\"手持游戏控制器或键盘鼠标，可能佩戴耳机\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"专注或兴奋的表情，眼神聚焦屏幕，嘴角微扬\"},{\"tag_name\":\"动作姿态\",\"tag_value\":\"打游戏时的动作，如双手操作控制器，身体前倾，做出按键或摇杆动作\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"室内游戏环境，如卧室或客厅，有电视或电脑屏幕\"},{\"tag_name\":\"光源类型\",\"tag_value\":\"室内人工光源，主要来自屏幕的蓝光和房间顶灯\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"屏幕光突出冷蓝色，环境光为暖色调，形成对比\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"沉浸式游戏体验，兴奋而专注的氛围\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高清图像，人物动作流畅，表情生动，画面清晰有细节\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/235513_f2c556a9b3c3456bba5cd6738e4b113d.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','985a4d28e14a49ce94ef79bca4685a45',NULL,NULL,NULL,'2026-09-07 23:54:13.013','2026-09-07 23:54:13.248','2026-09-07 23:55:43.845','2026-09-07 23:55:43.846');
INSERT INTO `attempts` VALUES ('316bfe3b-c450-4015-8cbd-a0cf158bbd8c','430d7679-1ecb-4600-8914-3d209cbf92fb',2,'succeeded','将参考图像中的主体，转化为一幅可爱、古怪的手绘涂鸦插画。\r\n\r\n采用极简的儿童故事书 / 时装速写美学，使用松散、不完美的黑色墨水线条，可见的铅笔涂鸦笔触，细微的交叉排线，以及迷人的手工质感。在保持参考图像中人物可识别的面部特征、发型、脸型、服饰、配饰和整体身份的同时，将它们简化成一个可爱的插图角色。\r\n\r\n角色设计：\r\n\r\n大脑袋和简化的小身体\r\n\r\n简单的点状眼睛和极小的嘴巴\r\n\r\n柔和圆润的面部特征\r\n\r\n脸颊上淡淡的粉红色红晕\r\n\r\n凌乱、富有表现力的手绘头发，带有许多松散的素描线\r\n\r\n略微夸张、好玩的形体比例\r\n\r\n自然放松的姿势，带有奇思妙想的时装插画感\r\n\r\n艺术风格：\r\n\r\n黑白铅笔 / 墨水涂鸦\r\n\r\n粗糙、不完美的素描线，而非干净的数字描边\r\n\r\n密集的涂鸦式头发和衣物细节\r\n\r\n浅淡的手绘色彩点缀\r\n\r\n微妙的水彩 / 蜡笔质感上色\r\n\r\n极简的明暗处理\r\n\r\n白色或米白色干净背景\r\n\r\n大量留白\r\n\r\n可爱、天真、俏皮、舒适的美学\r\n\r\n看起来像原创的手工笔记本 / 时尚涂鸦插画\r\n\r\n保留参考图像中的重要细节，同时将所有内容转化为一致的涂鸦风格。最终图像应呈现手绘感、略显不完美、讨喜、富有表现力且毫不费力的时尚感，而不是精致的矢量图或3D卡通。','gpt-image-2','1024x1024','medium','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/08/30/210724_5a046110edab4ea9981e8af0e11f041d.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','f6ea7d895b0940819ab7e018ffcbe644',NULL,NULL,NULL,'2026-08-30 21:06:34.993',NULL,NULL,'2026-08-30 21:14:34.546');
INSERT INTO `attempts` VALUES ('31c2a272-2026-433b-a35c-9a778c2b1b03','4d2aec28-4737-4260-8e73-efa677bdefcc',1,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"想要生成明信片风格的图片,上侧是[门尼演唱会.jpg]原图,下侧是明信片风格的图片,\",\"references\":[\"门尼演唱会.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"明信片风格，具有艺术化、复古或装饰性处理\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"上下分割构图，上侧保留演唱会原图的真实感，下侧应用明信片风格化\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"室内或室外演唱会现场，有舞台和观众\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"演唱会舞台背景，包括灯光、设备和人群\"},{\"tag_name\":\"光线方向\",\"tag_value\":\"来自舞台的多彩聚光灯和现场照明\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"鲜艳动态的色彩，突出舞台灯光效果，下半部分更柔和或艺术化\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"热烈、兴奋、充满活力的音乐会氛围\"},{\"tag_name\":\"负面元素\",\"tag_value\":\"避免模糊、失真或与明信片风格不协调的元素\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高分辨率、清晰细节，适合明信片印刷\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/175052_df41b78162634321b004358ae591149b.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','5ad248212f9a4d31b965d0cf561c7b0d',NULL,NULL,NULL,'2026-09-07 17:50:03.590','2026-09-07 17:50:04.643','2026-09-07 17:51:00.548','2026-09-07 17:51:00.549');
INSERT INTO `attempts` VALUES ('4fa56c02-525d-4e36-ab0e-2c195536f476','f924e8c4-b4ac-41bc-93c4-3642791d5325',1,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"建议保留原图的暖光与中式庭院结构,把氛围往“雨后静谧电影夜景”推\",\"references\":[\"路灯.jpg\"],\"tags_prompt\":[{\"tag_name\":\"构图方式\",\"tag_value\":\"保留夜晚庭院木栅栏、树干与双灯笼路灯的纵向构图，灯笼作为视觉焦点，画面更干净有层次\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"深邃暗部，暖金色灯光柔和扩散，细微光晕与薄雾，明暗对比克制，营造安静的夜游感\"},{\"tag_name\":\"环境动态\",\"tag_value\":\"加入若隐若现的树叶、潮湿石板路反光、少量漂浮微尘或细雨，远处保留朦胧灯火\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"电影感夜景摄影，低饱和暖棕与墨黑色调，细腻暗部层次，自然胶片颗粒，高级且真实\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"去除底部水印与无关文字，避免过曝灯泡、杂乱背景、过度 HDR、塑料感和不自然锐化  “你的构想”可以写：\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/02/205454_0e83be5f66004356b497eff9780ecf35.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','3da90772af79453fb71ebb3933c3dc93',NULL,NULL,NULL,'2026-09-02 20:54:11.519','2026-09-02 20:54:12.773','2026-09-02 20:54:56.535','2026-09-02 21:49:04.830');
INSERT INTO `attempts` VALUES ('51c089aa-62ea-45a4-ad72-0c7b1bfb9c26','f924e8c4-b4ac-41bc-93c4-3642791d5325',5,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"以这张夜晚庭院灯笼照片为基础优化,不改变主体位置和纵向构图。保留中式木栅栏、树干与两盏暖黄色灯笼,强化静谧、温暖、略带孤独感的电影夜景氛围；加入轻薄夜雾、潮湿地面的微弱反光、少量细雨或空气微尘,让灯光自然扩散。整体采用低饱和暖棕与墨黑色调,暗部有细节\\n画面干净克制,去除底部水印和文字。\",\"references\":[\"路灯.jpg\"],\"tags_prompt\":[{\"tag_name\":\"构图方式\",\"tag_value\":\"保留夜晚庭院木栅栏、树干与双灯笼路灯的纵向构图，灯笼作为视觉焦点，画面更干净有层次\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"深邃暗部，暖金色灯光柔和扩散，细微光晕与薄雾，明暗对比克制，营造安静的夜游感\"},{\"tag_name\":\"环境动态\",\"tag_value\":\"加入若隐若现的树叶、潮湿石板路反光、少量漂浮微尘或细雨，远处保留朦胧灯火\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"电影感夜景摄影，低饱和暖棕与墨黑色调，细腻暗部层次，自然胶片颗粒，高级且真实\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"去除底部水印与无关文字，避免过曝灯泡、杂乱背景、过度 HDR、塑料感和不自然锐化\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/03/100007_2218d74303114923bee0bb0b6ec141c7.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','6100ac2a68d14fcf80579c67e69c2dd9',NULL,NULL,NULL,'2026-09-03 09:59:34.472','2026-09-03 10:01:23.526','2026-09-03 10:01:23.526','2026-09-03 10:01:23.568');
INSERT INTO `attempts` VALUES ('576cfe37-c1df-4e00-aa9a-489f23fa6dd2','8502450e-b6a2-422a-bea8-aeab580cfdbe',2,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"帮我构建一张有趣的动画图,人物原型是[薛之谦.jpg]\",\"references\":[\"薛之谦.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"混乱搞笑的低技巧手绘涂鸦，像用廉价马克笔或蜡笔快速画成\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"夸张五官与笨拙比例，保留人物辨识度，歪眼、大头、小身体、滑稽表情\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"粗糙抖动的儿童画线条，潦草涂改、重叠轮廓、随意 scribble 和意外笔触\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简化且透视歪斜的建筑、树木、云朵和街道，加入箭头、星星、旋涡和小字涂鸦\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"随意不均匀的填色，蜡笔纹理、马克笔渗色、纸张颗粒和不规则阴影，整体荒诞活泼、故意不精致\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/03/203736_bddbe18e9daf40f2bfeffd9692494acf.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','3fcdf029e2d442b1ba13a613dc35d438',NULL,NULL,NULL,'2026-09-03 20:36:35.185','2026-09-03 20:36:41.349','2026-09-03 20:37:39.539','2026-09-03 20:37:39.540');
INSERT INTO `attempts` VALUES ('5f8721bc-bfca-4ecc-b962-a0fc3d7dcfd3','94f1341e-9a08-4832-bd51-30c6dd5525b3',4,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"[任务模型.png]保持人物模型不变,然后丰富任务的动作与表情,然后是一个摄影时的动作与状态\",\"references\":[\"任务模型.png\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"一个人物模型\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"单人\"},{\"tag_name\":\"外观特征\",\"tag_value\":\"保持原模型的外观特征，如面部轮廓、发型、体型不变\"},{\"tag_name\":\"服饰配件\",\"tag_value\":\"原模型的服饰和配件，保持不变\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"丰富生动的表情，如微笑、专注、自然放松，根据摄影动作动态调整\"},{\"tag_name\":\"动作姿态\",\"tag_value\":\"摆出摄影时的自然动作，如手持相机调整参数、侧身摆姿势、或作为被拍摄者的优雅站姿\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"摄影工作室或户外摄影环境，如简约背景或自然外景\"},{\"tag_name\":\"光线方向\",\"tag_value\":\"摄影常用光线，如柔和的侧光或自然光从窗外照射，营造立体感和专业氛围\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"真实摄影风格，注重细节还原和质感表现\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"专业、专注且略带创意的摄影氛围\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高清摄影画面，人物对焦清晰，动作和表情细节丰富，背景适度虚化\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/08/001243_e9413ad19b3544eb8e906b3f2d98d064.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}, {\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/08/001243_0ec4c3474e384bbf9cfd9f27b865a910.png\", \"mimeType\": \"image/png\", \"sortOrder\": 2}]','787ea2f11e8648ebbf3ef11e2d20e352',NULL,NULL,NULL,'2026-09-08 00:11:32.605','2026-09-08 00:11:32.838','2026-09-08 00:12:45.176','2026-09-08 00:12:45.177');
INSERT INTO `attempts` VALUES ('62b4e86c-cc66-40f2-bf0d-c7b99826987a','4d2aec28-4737-4260-8e73-efa677bdefcc',3,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"想要生成明信片风格的图片,上侧是[门尼演唱会.jpg]原图,下侧是明信片风格的图片,明信片需要的是简约风格,抽象出重点的人与事物,地点特色,颜色选取需要有特色,画面要有美感\",\"references\":[\"门尼演唱会.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"明信片风格，简约主义，抽象化设计\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"上下分割布局，上侧保留原图参考区域，下侧为简约明信片风格画面\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"画面适当留白，增强简约感和呼吸感\"},{\"tag_name\":\"主体类型\",\"tag_value\":\"演唱会场景中的人与事物，经过抽象化处理，突出关键元素\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"演唱会场地，具有地点特色，如舞台或观众席的抽象表现\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"颜色选取有特色，采用鲜艳对比或主题色系，增强视觉吸引力\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"根据演唱会氛围选择感染力强的色彩，如暖色调或霓虹色\"},{\"tag_name\":\"媒介形式\",\"tag_value\":\"明信片印刷风格，平面设计感，表面平滑\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"艺术美感，简约而富有表现力，传递演唱会活力\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"抽象出重点人物、事物和地点特色，简化非必要细节，保持画面干净\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高质量明信片印刷效果，图像清晰，色彩准确，整体美观\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/175830_1d8abfa633af4564b32f5ae7537665c6.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','4d0df969213a49ffa93e3cdd65ec960b',NULL,NULL,NULL,'2026-09-07 17:57:33.896','2026-09-07 17:57:34.133','2026-09-07 17:58:33.531','2026-09-07 17:58:33.532');
INSERT INTO `attempts` VALUES ('62c67775-adce-4b5f-9dd6-b927aadc27db','eabcc7c4-1c2e-4339-94e7-2ff3d0e035f7',1,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"[玫瑰礼堂.jpg]原图在上面,AI生成的部分在下面,浪漫风格,不要具象,使用抽象风格,然后颜色选取需要情感色彩强烈,浓墨触笔\",\"references\":[\"玫瑰礼堂.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"浪漫抽象风格，融合情感表达与抽象艺术\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"使用浓墨触笔，笔触厚重且富有表现力\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"选取情感色彩强烈的颜色，如深红、紫色等暖色调，以增强情感共鸣\"},{\"tag_name\":\"色彩饱和度\",\"tag_value\":\"高饱和度色彩，突出情感强度\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"营造浪漫、梦幻的氛围\"},{\"tag_name\":\"负面元素\",\"tag_value\":\"避免任何具象物体或细节，保持画面完全抽象\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"画面采用上下分割构图，上半部分以抽象形式暗示玫瑰礼堂的轮廓或元素，下半部分为AI生成的抽象艺术表达\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/191300_41ccb9ecb9f643c5a1245ec6093d6f74.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','007b911da1784513871dd1e2dc22dd5d',NULL,NULL,NULL,'2026-09-07 19:12:10.985','2026-09-07 19:12:11.015','2026-09-07 19:13:01.758','2026-09-07 19:13:01.759');
INSERT INTO `attempts` VALUES ('6d299d78-d7d0-403f-bc2a-52163c9ec4ba','4d2aec28-4737-4260-8e73-efa677bdefcc',6,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"想要生成明信片风格的图片,上侧是[门尼演唱会.jpg]原图,下侧是明信片风格的图片,明信片需要的是简约风格,抽象出重点的人与事物,地点特色,颜色选取需要有特色,画面要有美感;抽象风格,不必展示整体,然后要有文字在明信片的右侧\",\"references\":[\"门尼演唱会.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"简约抽象风格，提炼演唱会场景的关键元素，省略不必要的细节\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"上下分割构图，上半部分为演唱会原图参考，下半部分为抽象明信片设计\"},{\"tag_name\":\"主体类型\",\"tag_value\":\"抽象化的表演者、乐器或演唱会相关物体\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"演唱会现场，突出舞台或人群特色地点\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"选取特色鲜明的颜色，如霓虹色或高饱和度对比色，增强视觉冲击力\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"布局中留白合理，确保画面透气，文字与图形元素协调\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简约背景，避免杂乱，突出前景抽象元素\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"传达演唱会的活力或抽象艺术的美感\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高美感画面，抽象但不失识别性，风格统一优雅\"},{\"tag_name\":\"文字元素\",\"tag_value\":\"在明信片右侧区域添加简短文字，\\\"印IN\\\"，字体风格符合原图风格，与整体抽象设计协调\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/185420_73d0719576de44238369ad5519a199d6.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','7221f27853774691b0f11f7bc9635310',NULL,NULL,NULL,'2026-09-07 18:53:26.328','2026-09-07 18:53:27.471','2026-09-07 18:54:22.529','2026-09-07 18:54:22.530');
INSERT INTO `attempts` VALUES ('75c812e0-a770-4ce6-b582-febb6bce43cb','f924e8c4-b4ac-41bc-93c4-3642791d5325',3,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"以这张夜晚庭院灯笼照片为基础优化,不改变主体位置和纵向构图。保留中式木栅栏、树干与两盏暖黄色灯笼,强化静谧、温暖、略带孤独感的电影夜景氛围；加入轻薄夜雾、潮湿地面的微弱反光、少量细雨或空气微尘,让灯光自然扩散。整体采用低饱和暖棕与墨黑色调,暗部有细节\\n画面干净克制,去除底部水印和文字。\",\"references\":[\"参考图\"],\"tags_prompt\":[{\"tag_name\":\"构图方式\",\"tag_value\":\"保留夜晚庭院木栅栏、树干与双灯笼路灯的纵向构图，灯笼作为视觉焦点，画面更干净有层次\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"深邃暗部，暖金色灯光柔和扩散，细微光晕与薄雾，明暗对比克制，营造安静的夜游感\"},{\"tag_name\":\"环境动态\",\"tag_value\":\"加入若隐若现的树叶、潮湿石板路反光、少量漂浮微尘或细雨，远处保留朦胧灯火\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"电影感夜景摄影，低饱和暖棕与墨黑色调，细腻暗部层次，自然胶片颗粒，高级且真实\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"去除底部水印与无关文字，避免过曝灯泡、杂乱背景、过度 HDR、塑料感和不自然锐化\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/02/214904_02fe045fa44a40f99089481fd1d93e89.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','6ce5762730df4c6e8914e9f7ea176d4d',NULL,NULL,NULL,'2026-09-02 21:48:17.227','2026-09-02 21:48:59.091','2026-09-02 21:49:04.851','2026-09-02 21:49:04.853');
INSERT INTO `attempts` VALUES ('7d05e0de-ff97-4514-b4aa-0ac7d868cdc8','430d7679-1ecb-4600-8914-3d209cbf92fb',3,'succeeded','将参考图像中的主体，转化为一幅可爱、古怪的手绘涂鸦插画。\r\n\r\n采用极简的儿童故事书 / 时装速写美学，使用松散、不完美的黑色墨水线条，可见的铅笔涂鸦笔触，细微的交叉排线，以及迷人的手工质感。在保持参考图像中人物可识别的面部特征、发型、脸型、服饰、配饰和整体身份的同时，将它们简化成一个可爱的插图角色。\r\n\r\n角色设计：\r\n\r\n大脑袋和简化的小身体\r\n\r\n简单的点状眼睛和极小的嘴巴\r\n\r\n柔和圆润的面部特征\r\n\r\n脸颊上淡淡的粉红色红晕\r\n\r\n凌乱、富有表现力的手绘头发，带有许多松散的素描线\r\n\r\n略微夸张、好玩的形体比例\r\n\r\n自然放松的姿势，带有奇思妙想的时装插画感\r\n\r\n艺术风格：\r\n\r\n黑白铅笔 / 墨水涂鸦\r\n\r\n粗糙、不完美的素描线，而非干净的数字描边\r\n\r\n密集的涂鸦式头发和衣物细节\r\n\r\n浅淡的手绘色彩点缀\r\n\r\n微妙的水彩 / 蜡笔质感上色\r\n\r\n极简的明暗处理\r\n\r\n白色或米白色干净背景\r\n\r\n大量留白\r\n\r\n可爱、天真、俏皮、舒适的美学\r\n\r\n看起来像原创的手工笔记本 / 时尚涂鸦插画\r\n\r\n保留参考图像中的重要细节，同时将所有内容转化为一致的涂鸦风格。最终图像应呈现手绘感、略显不完美、讨喜、富有表现力且毫不费力的时尚感，而不是精致的矢量图或3D卡通。','gpt-image-2','1024x1024','medium','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/08/30/211129_ba778c5185624358a7ab74c04000af84.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','5d7b5d3284634a1bb4b57a93e85eaa47',NULL,NULL,NULL,'2026-08-30 21:10:29.125',NULL,NULL,'2026-08-30 21:14:34.552');
INSERT INTO `attempts` VALUES ('9aa444f9-333c-431e-bcb8-cc2afa77e992','7271d4a0-2bdd-4b34-909a-4dc0817dbd89',4,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"把人物[人物.jpg]做成[样例.png]的风格的3D卡通图,人物上半身要全部展示出,展示出正面视角,方便后续建模,衣服需要换成格子衬衫\",\"references\":[\"样例.png\",\"人物.jpg\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"人物\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"单人\"},{\"tag_name\":\"服饰配件\",\"tag_value\":\"上半身穿着格子衬衫，衬衫纹理清晰\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"中性表情，适合3D建模参考\"},{\"tag_name\":\"动作姿态\",\"tag_value\":\"正面站立，上半身正对镜头，姿势标准自然\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"正面半身构图，人物居中，上半身全部展示\"},{\"tag_name\":\"景别范围\",\"tag_value\":\"半身景别，从头顶到腰部\"},{\"tag_name\":\"拍摄视角\",\"tag_value\":\"正面平视视角\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"3D卡通风格\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"3D渲染，卡通化处理，表面光滑\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简洁的纯色或渐变背景，无复杂元素\"},{\"tag_name\":\"光线设置\",\"tag_value\":\"均匀的柔和光线，无强烈阴影，照亮整个上半身\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"人物细节完整，衬衫纹理清晰，适合后续建模\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高分辨率图像，细节锐利，色彩准确\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/211108_4bfa508431564d1893f3ca75d7f0823a.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','b5358ca148354fdca862f6060f43f013',NULL,NULL,NULL,'2026-09-07 21:10:23.150','2026-09-07 21:10:23.437','2026-09-07 21:11:10.903','2026-09-07 21:11:10.904');
INSERT INTO `attempts` VALUES ('a6133953-421d-4de7-b9e8-e7a2868aac8f','eabcc7c4-1c2e-4339-94e7-2ff3d0e035f7',3,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"[玫瑰礼堂.jpg]原图在上面,AI生成的部分在下面,浪漫风格,不要具象,使用抽象风格,然后颜色选取需要情感色彩强烈\\n蓝色\\n黑色与红色等等；,浓墨触笔但又要具有简约的感觉,增加想象力\\n给画面增添一些元素\\n比如有人求婚\\n然后任务风格简约型\",\"references\":[\"玫瑰礼堂.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"抽象简约浪漫风格，避免具象写实，突出想象力\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"情感色彩强烈，以蓝色、黑色和红色为主色调\"},{\"tag_name\":\"色彩饱和度\",\"tag_value\":\"高饱和度，增强情感表达和视觉冲击力\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"蓝色、黑色与红色形成对比鲜明的抽象色彩组合\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"浓墨触笔风格，笔触大胆但整体保持简约感\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"抽象化的礼堂或浪漫场景，暗示求婚氛围\"},{\"tag_name\":\"主体类型\",\"tag_value\":\"抽象化的人物元素，表现求婚场景\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"至少两人，体现求婚互动\"},{\"tag_name\":\"主体关系\",\"tag_value\":\"求婚者与被求婚者的关系\"},{\"tag_name\":\"动作姿态\",\"tag_value\":\"抽象化的求婚姿态，如跪姿或递送信物\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"浪漫、强烈情感，充满想象力和叙事感\"},{\"tag_name\":\"负面元素\",\"tag_value\":\"避免具象细节和写实描绘，保持抽象简约\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"简约而富有想象力的抽象画面，色彩鲜明，构图留白\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/192314_0de9ce2d465b4c44b89f523f472acbe2.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','e4dfacc6a9b345999d8c662ab40a7017',NULL,NULL,NULL,'2026-09-07 19:21:57.726','2026-09-07 19:21:57.959','2026-09-07 19:23:15.388','2026-09-07 19:23:15.389');
INSERT INTO `attempts` VALUES ('a9502759-0707-4cd2-9fb3-f7a305030026','fa8f3af9-0c43-4e48-98d5-202856b8e52d',4,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"为长沙创作一幅温暖、友好的编辑式旅行插画。强调至少要有[橘子洲头.png]和[天心阁.png]\",\"references\":[],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"长沙的地标建筑、特色街景、当地交通、自然景观、植物、动物、美食与文化物件\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"各元素自然组合并适度重叠，保持疏朗通透\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"平衡的编辑式构图，类似旅行手账或设计师速写本\"},{\"tag_name\":\"主体位置\",\"tag_value\":\"主体元素分散布局，避免集中堆叠\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"大面积留白，每个元素保持呼吸感\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"长沙\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简洁留白背景，不绘制复杂城市全景\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"手绘旅行手账、精品旅行指南、当代杂志插画\"},{\"tag_name\":\"参考流派\",\"tag_value\":\"编辑式旅行插画、极简涂鸦\"},{\"tag_name\":\"媒介形式\",\"tag_value\":\"黑色毡尖笔\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"扁平化绘制，简化形状，极少内部细节\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"线条略微摇晃，粗细自然变化，松弛随性，保留手绘瑕疵\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"黑白为主\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"仅使用一种强调色 黑色\"},{\"tag_name\":\"色彩饱和度\",\"tag_value\":\"强调色低面积、克制使用\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"平面照明，无渐变与高光\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"温暖、友好、轻松、俏皮、简约、优雅\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"强调 长沙最具辨识度的文化与地域特征；线条自然断开、偶有重叠，体现手工绘制的不完美；强调色仅用于水面、天空、窗户、招牌、服饰点缀、装饰高光或少量建筑细节\"},{\"tag_name\":\"负面元素\",\"tag_value\":\"避免写实城市景观、照片感、3D效果、渐变、厚重阴影、油画笔触、复杂纹理、金属光泽、机械精确轮廓、矢量风格、过度细节、拥挤构图、额外颜色\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"干净、通透、平面化、图形感强，突出手工毡尖笔涂鸦质感\"}]}','gpt-image-2','auto','auto','png',1,'text-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/03/200532_d84d536a341449c5a84baf5b2fc5c744.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','5b1ece40f4a44737af8b170f2f5b3cbb',NULL,NULL,NULL,'2026-09-03 20:04:31.432','2026-09-03 20:04:32.465','2026-09-03 20:05:34.349','2026-09-03 20:05:34.351');
INSERT INTO `attempts` VALUES ('aed8f434-61d5-4382-88ad-e993b91ee0e2','430d7679-1ecb-4600-8914-3d209cbf92fb',1,'succeeded','将参考图像中的主体，转化为一幅可爱、古怪的手绘涂鸦插画。\r\n\r\n采用极简的儿童故事书 / 时装速写美学，使用松散、不完美的黑色墨水线条，可见的铅笔涂鸦笔触，细微的交叉排线，以及迷人的手工质感。在保持参考图像中人物可识别的面部特征、发型、脸型、服饰、配饰和整体身份的同时，将它们简化成一个可爱的插图角色。\r\n\r\n角色设计：\r\n\r\n大脑袋和简化的小身体\r\n\r\n简单的点状眼睛和极小的嘴巴\r\n\r\n柔和圆润的面部特征\r\n\r\n脸颊上淡淡的粉红色红晕\r\n\r\n凌乱、富有表现力的手绘头发，带有许多松散的素描线\r\n\r\n略微夸张、好玩的形体比例\r\n\r\n自然放松的姿势，带有奇思妙想的时装插画感\r\n\r\n艺术风格：\r\n\r\n黑白铅笔 / 墨水涂鸦\r\n\r\n粗糙、不完美的素描线，而非干净的数字描边\r\n\r\n密集的涂鸦式头发和衣物细节\r\n\r\n浅淡的手绘色彩点缀\r\n\r\n微妙的水彩 / 蜡笔质感上色\r\n\r\n极简的明暗处理\r\n\r\n白色或米白色干净背景\r\n\r\n大量留白\r\n\r\n可爱、天真、俏皮、舒适的美学\r\n\r\n看起来像原创的手工笔记本 / 时尚涂鸦插画\r\n\r\n保留参考图像中的重要细节，同时将所有内容转化为一致的涂鸦风格。最终图像应呈现手绘感、略显不完美、讨喜、富有表现力且毫不费力的时尚感，而不是精致的矢量图或3D卡通。','gpt-image-2','1024x1024','medium','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/08/30/210436_06f5a577106841f88ccf61f9b329d94a.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','ac694e0bead9447fba88155b6bb5d3f6',NULL,NULL,NULL,'2026-08-30 21:03:51.160',NULL,NULL,'2026-08-30 21:14:34.539');
INSERT INTO `attempts` VALUES ('b2785198-31da-4bd8-a7d6-9c4a347db888','8502450e-b6a2-422a-bea8-aeab580cfdbe',1,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"帮我构建一张有趣的动画图,人物原型是[薛之谦.jpg]\",\"references\":[\"薛之谦.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"混乱搞笑的低技巧手绘涂鸦，像用廉价马克笔或蜡笔快速画成\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"夸张五官与笨拙比例，保留人物辨识度，歪眼、大头、小身体、滑稽表情\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"粗糙抖动的儿童画线条，潦草涂改、重叠轮廓、随意 scribble 和意外笔触\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简化且透视歪斜的建筑、树木、云朵和街道，加入箭头、星星、旋涡和小字涂鸦\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"随意不均匀的填色，蜡笔纹理、马克笔渗色、纸张颗粒和不规则阴影，整体荒诞活泼、故意不精致\"}]}','gpt-image-2','auto','auto','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/01/231002_56f3df624a344fc8854a1fd252628730.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','1ef32c69ac2d4bb0a57a87830ab3c9c7',NULL,NULL,NULL,'2026-09-01 23:08:35.532',NULL,NULL,'2026-09-01 23:10:05.218');
INSERT INTO `attempts` VALUES ('b92160c2-a554-4611-afa1-f47fbc7d1bb0','4d2aec28-4737-4260-8e73-efa677bdefcc',4,'failed','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"想要生成明信片风格的图片,上侧是[门尼演唱会.jpg]原图,下侧是明信片风格的图片,明信片需要的是简约风格,抽象出重点的人与事物,地点特色,颜色选取需要有特色,画面要有美感;抽象风格,不必展示整体,然后要有文字在明信片的右侧\",\"references\":[\"门尼演唱会.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"简约抽象风格，提炼演唱会场景的关键元素，省略不必要的细节\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"上下分割构图，上半部分为演唱会原图参考，下半部分为抽象明信片设计\"},{\"tag_name\":\"主体类型\",\"tag_value\":\"抽象化的表演者、乐器或演唱会相关物体\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"演唱会现场，突出舞台或人群特色地点\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"选取特色鲜明的颜色，如霓虹色或高饱和度对比色，增强视觉冲击力\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"布局中留白合理，确保画面透气，文字与图形元素协调\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简约背景，避免杂乱，突出前景抽象元素\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"传达演唱会的活力或抽象艺术的美感\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高美感画面，抽象但不失识别性，风格统一优雅\"},{\"tag_name\":\"文字元素\",\"tag_value\":\"在明信片右侧区域添加简短文字，\\\"印IN\\\"，字体风格符合原图风格，与整体抽象设计协调\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[]','b113d4f929fd43ff9b5b749b8115417b',NULL,'阿里云 OSS 需要安装 oss2 依赖包',NULL,'2026-09-07 18:47:51.771','2026-09-07 18:47:52.680','2026-09-07 18:48:43.116','2026-09-07 18:48:43.118');
INSERT INTO `attempts` VALUES ('c12eaf39-363d-4869-bb15-261db4b5aee3','fa8f3af9-0c43-4e48-98d5-202856b8e52d',1,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"为长沙创作一幅温暖、友好的编辑式旅行插画。强调至少要有[橘子洲头.png]和[天心阁.png]\",\"references\":[\"橘子洲头.png\",\"天心阁.png\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"长沙的地标建筑、特色街景、当地交通、自然景观、植物、动物、美食与文化物件\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"各元素自然组合并适度重叠，保持疏朗通透\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"平衡的编辑式构图，类似旅行手账或设计师速写本\"},{\"tag_name\":\"主体位置\",\"tag_value\":\"主体元素分散布局，避免集中堆叠\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"大面积留白，每个元素保持呼吸感\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"长沙\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简洁留白背景，不绘制复杂城市全景\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"手绘旅行手账、精品旅行指南、当代杂志插画\"},{\"tag_name\":\"参考流派\",\"tag_value\":\"编辑式旅行插画、极简涂鸦\"},{\"tag_name\":\"媒介形式\",\"tag_value\":\"黑色毡尖笔\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"扁平化绘制，简化形状，极少内部细节\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"线条略微摇晃，粗细自然变化，松弛随性，保留手绘瑕疵\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"黑白为主\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"仅使用一种强调色 黑色\"},{\"tag_name\":\"色彩饱和度\",\"tag_value\":\"强调色低面积、克制使用\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"平面照明，无渐变与高光\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"温暖、友好、轻松、俏皮、简约、优雅\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"强调 长沙最具辨识度的文化与地域特征；线条自然断开、偶有重叠，体现手工绘制的不完美；强调色仅用于水面、天空、窗户、招牌、服饰点缀、装饰高光或少量建筑细节\"},{\"tag_name\":\"负面元素\",\"tag_value\":\"避免写实城市景观、照片感、3D效果、渐变、厚重阴影、油画笔触、复杂纹理、金属光泽、机械精确轮廓、矢量风格、过度细节、拥挤构图、额外颜色\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"干净、通透、平面化、图形感强，突出手工毡尖笔涂鸦质感\"}]}','gpt-image-2','auto','auto','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/01/205916_ea31f5383ec24445aa2efe8dbff4dabb.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','ad2bf756bff64c2aa71f986101e8ef77',NULL,NULL,NULL,'2026-09-01 20:58:18.190',NULL,NULL,'2026-09-01 20:59:18.220');
INSERT INTO `attempts` VALUES ('c29328bc-27de-43dd-a3c9-0165d0ab0c36','aa856be5-df37-4f93-be9d-6bbe955eb041',1,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"以这张夜晚庭院灯笼照片为基础优化,不改变主体位置和纵向构图。保留中式木栅栏、树干与两盏暖黄色灯笼,强化静谧、温暖、略带孤独感的电影夜景氛围；加入轻薄夜雾、潮湿地面的微弱反光、少量细雨或空气微尘,让灯光自然扩散。整体采用低饱和暖棕与墨黑色调,暗部有细节\\n画面干净克制,去除底部水印和文字。\",\"references\":[\"路灯.jpg\"],\"tags_prompt\":[{\"tag_name\":\"构图方式\",\"tag_value\":\"保留夜晚庭院木栅栏、树干与双灯笼路灯的纵向构图，灯笼作为视觉焦点，画面更干净有层次\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"深邃暗部，暖金色灯光柔和扩散，细微光晕与薄雾，明暗对比克制，营造安静的夜游感\"},{\"tag_name\":\"环境动态\",\"tag_value\":\"加入若隐若现的树叶、潮湿石板路反光、少量漂浮微尘或细雨，远处保留朦胧灯火\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"电影感夜景摄影，低饱和暖棕与墨黑色调，细腻暗部层次，自然胶片颗粒，高级且真实\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"去除底部水印与无关文字，避免过曝灯泡、杂乱背景、过度 HDR、塑料感和不自然锐化\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/03/090431_d49206ac9f214329a41ea3570399f91b.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','27e5a76a8ce94d57b74e00ec5a5e3872',NULL,NULL,NULL,'2026-09-03 09:04:01.377','2026-09-03 09:04:02.647','2026-09-03 09:04:34.228','2026-09-03 09:04:34.230');
