INSERT INTO `attempts` VALUES ('d542b776-7eb3-4eef-a685-ae3db3fb5ee8','8502450e-b6a2-422a-bea8-aeab580cfdbe',3,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"帮我构建一张有趣的动画图,人物原型是[薛之谦.jpg]\",\"references\":[\"薛之谦.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"混乱搞笑的低技巧手绘涂鸦，像用廉价马克笔或蜡笔快速画成\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"夸张五官与笨拙比例，保留人物辨识度，歪眼、大头、小身体、滑稽表情\"},{\"tag_name\":\"笔触质感\",\"tag_value\":\"粗糙抖动的儿童画线条，潦草涂改、重叠轮廓、随意 scribble 和意外笔触\"},{\"tag_name\":\"背景内容\",\"tag_value\":\"简化且透视歪斜的建筑、树木、云朵和街道，加入箭头、星星、旋涡和小字涂鸦\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"随意不均匀的填色，蜡笔纹理、马克笔渗色、纸张颗粒和不规则阴影，整体荒诞活泼、故意不精致\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/03/204409_44d7e9a3eb7149b0a842b1ae5554da2c.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','cb80d05d312149fba58ec332d696cfa0',NULL,NULL,NULL,'2026-09-03 20:42:45.317','2026-09-03 20:42:45.562','2026-09-03 20:44:10.203','2026-09-03 20:44:10.203');
INSERT INTO `attempts` VALUES ('d6832cf5-a456-11f1-9a95-40c2ba597463','d68014a4-a456-11f1-9a95-40c2ba597463',1,'succeeded','夕阳下的校园一角，温暖的橙黄色光线，安静的电影感构图。','gpt-image-2','1024x1024','standard','png',1,'text-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/08/30/145915_e824df17fc5149ceb572fe9013334be5.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','mock-task-d6898c33-a456-11f1-9a95-40c2ba597463',NULL,NULL,'{\"provider\": \"mock\", \"queueTimeMs\": 0, \"totalTimeMs\": 12000, \"inferenceTimeMs\": 12000}','2026-08-30 17:40:29.865','2026-08-30 17:40:29.865','2026-08-30 17:40:29.865','2026-08-30 18:42:28.590');
INSERT INTO `attempts` VALUES ('d80e8580-4b01-4933-b055-dbc253ea542a','94f1341e-9a08-4832-bd51-30c6dd5525b3',2,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"[任务模型.png]保持人物模型不变,然后丰富任务的动作与表情,然后是一个摆烂的神情与动作\",\"references\":[\"任务模型.png\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"人物\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"单人\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"摆烂的神情：疲惫、无神、嘴角下撇，显得无精打采\"},{\"tag_name\":\"动作姿态\",\"tag_value\":\"摆烂的动作：瘫软地坐着或躺着，四肢伸展，姿态放松无力\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/234209_0a13a9c1e65d42ec9be75faa59aee7cd.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','e4b3268deb7445c9a478ef23e71284e1',NULL,NULL,NULL,'2026-09-07 23:40:55.536','2026-09-07 23:40:55.750','2026-09-07 23:42:11.687','2026-09-07 23:42:11.688');
INSERT INTO `attempts` VALUES ('d8f4c1d9-83c7-4691-a8e6-94e92cda0e39','ae530508-f338-46e4-8b98-41eff31714ef',1,'succeeded','将这张照片变成一幅混乱有趣的涂鸦插画，刻意画得凌乱且技法拙劣，仿佛是用廉价记号笔、蜡笔或磨损的毡头笔在纸上快速勾勒出来的。\r\n\r\n夸张的面部特征要带有笨拙的比例——夸张的表情，过大的脑袋、极小的身体、歪斜的笑容，以及笨手笨脚的人体结构，但依然要能认出画的是谁。用粗糙的、像小孩乱涂的线条，颤抖的手绘笔触，明显的涂改痕迹，重叠的轮廓，偶然蹭出的墨点，以及在画面四周随意添加的涂鸦。背景采用简单的卡通风格，但画得歪歪扭扭，有糟糕的建筑、树木、云朵、街道元素，以及毫无章法的透视。上色要看起来漫不经心且不完美，带有明显的笔触纹理、不均匀的填色区域、蜡笔的颗粒质感、马克笔的晕染效果，以及不规则的明暗处理。加入一些俏皮的瑕疵，比如被划掉的线条、未完成的细节、随意的箭头、小字注释、星星、漩涡纹样和抽象的乱涂。整体美学风格应显得幽默、即兴、手作感强、充满活力、滑稽可笑，并且刻意保持粗糙感，像是儿童素描本与无厘头网络梗图的混合体。要有丰富的纹理细节，可见的纸张颗粒，不对称的构图，别扭的画面取景，表现力十足的涂鸦混乱，以及原生态的速写能量。','gpt-image-2','1024x1024','medium','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/08/30/202300_7c402fcc1c4a48398961e7d3c575fdb0.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','62dd902a21244c1b9155b54401b9bacc',NULL,NULL,NULL,'2026-08-30 20:21:45.916',NULL,NULL,'2026-08-30 20:37:13.054');
INSERT INTO `attempts` VALUES ('eaec1d48-fec9-41fc-94b8-87dbfb090277','85d094a7-a20f-4b4e-bfee-847cf03a76f2',1,'succeeded','Turn the reference photo into a travel souvenir enamel pin badge. Compose it as a SCENE, not a single isolated object.\r\n\r\nSubject hierarchy: the defining landscape, terrain or landmark of the photo forms the main body of the badge and occupies most of its area. If a person appears prominently in the photo, keep them in the badge as a small, simplified figure at true relative scale within that landscape — the person is an accent, the landscape is the subject. Preserve the original spatial relationship and scale between the figure and the surroundings.\r\n\r\nHow to render the person: flat enamel color blocks matching their real clothing and hair color from the photo. The face is a smooth plain area of light skin-tone enamel with no drawn facial features — do NOT render the person as a dark or black silhouette, and do NOT black out the face or head. Skin reads as a warm light enamel color, clearly lighter than the clothing.\r\n\r\nStyling: thin polished gold outline around the silhouette and along every internal divider, glossy enamel color fill, gentle even lighting with only a soft sheen on the gold lines, very subtle drop shadow. Outer contour follows the scene\'s own shape, not a plain rectangle.\r\n\r\nBackground: flat dark navy coarse linen texture. Badge centered, filling about 60% of the frame.\r\n\r\nAvoid: black silhouette figure, blacked-out face, dark featureless head, portrait close-up, detailed facial features, person dominating the badge, cropping out the landscape, three-quarter angle, macro product photography, heavy specular glare, cartoon, realistic scene, text, watermark.','gpt-image-2','1024x1024','medium','png',1,NULL,'[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/08/30/201908_b02b720484a9466dbb7397559bc7fea5.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','e4d11107693e4918b34c920b5fb4a87a',NULL,NULL,NULL,'2026-08-30 20:17:40.304',NULL,NULL,'2026-08-30 20:19:26.937');
INSERT INTO `attempts` VALUES ('eb25c6d3-e49a-49f0-adf7-7f91eccbd018','4d2aec28-4737-4260-8e73-efa677bdefcc',2,'failed','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"想要生成明信片风格的图片,上侧是[门尼演唱会.jpg]原图,下侧是明信片风格的图片,明信片需要的是简约风格,抽象出重点的人与事物,地点特色,颜色选取需要有特色,画面要有美感\",\"references\":[\"门尼演唱会.jpg\"],\"tags_prompt\":[{\"tag_name\":\"整体风格\",\"tag_value\":\"明信片风格，简约主义，抽象化设计\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"上下分割布局，上侧保留原图参考区域，下侧为简约明信片风格画面\"},{\"tag_name\":\"留白空间\",\"tag_value\":\"画面适当留白，增强简约感和呼吸感\"},{\"tag_name\":\"主体类型\",\"tag_value\":\"演唱会场景中的人与事物，经过抽象化处理，突出关键元素\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"演唱会场地，具有地点特色，如舞台或观众席的抽象表现\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"颜色选取有特色，采用鲜艳对比或主题色系，增强视觉吸引力\"},{\"tag_name\":\"色彩倾向\",\"tag_value\":\"根据演唱会氛围选择感染力强的色彩，如暖色调或霓虹色\"},{\"tag_name\":\"媒介形式\",\"tag_value\":\"明信片印刷风格，平面设计感，表面平滑\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"艺术美感，简约而富有表现力，传递演唱会活力\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"抽象出重点人物、事物和地点特色，简化非必要细节，保持画面干净\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高质量明信片印刷效果，图像清晰，色彩准确，整体美观\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[]','b0c2ae63c62a430da86b6ae029fc9ab9',NULL,'Error code: 451 - {\'error\': {\'code\': \'image_safety\', \'message\': \'The generated image was filtered by the safety policy. Please adjust your prompt and try again.\', \'param\': None, \'request_id\': \'3266fb971477473b8d47ad319fca430f\', \'type\': \'invalid_request_error\'}}',NULL,'2026-09-07 17:55:24.468','2026-09-07 17:55:24.809','2026-09-07 17:56:13.471','2026-09-07 17:56:13.472');
INSERT INTO `attempts` VALUES ('eb898e6b-57b4-4be9-9477-fe247cbfed08','94f1341e-9a08-4832-bd51-30c6dd5525b3',5,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"[任务模型.png]保持人物模型不变,然后丰富任务的动作与表情,然后是一个写代码时痛苦的状态\",\"references\":[\"任务模型.png\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"一个正在写代码的人物\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"单人\"},{\"tag_name\":\"外观特征\",\"tag_value\":\"穿着日常便服，如T恤，头发略显凌乱以显示疲惫\"},{\"tag_name\":\"表情状态\",\"tag_value\":\"痛苦的表情，眉头紧锁，嘴角下垂，眼神疲惫\"},{\"tag_name\":\"动作姿态\",\"tag_value\":\"坐在电脑前，一手敲击键盘，另一手扶额或抱头，身体前倾\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"中景构图，人物置于画面中央，电脑屏幕清晰可见\"},{\"tag_name\":\"场景地点\",\"tag_value\":\"室内，家庭书房或办公室\"},{\"tag_name\":\"时间氛围\",\"tag_value\":\"深夜，窗外黑暗，室内光线昏暗\"},{\"tag_name\":\"光源类型\",\"tag_value\":\"主要来自电脑屏幕的冷色光，辅以微弱的室内顶灯\"},{\"tag_name\":\"整体色调\",\"tag_value\":\"冷色调，以蓝色和灰色为主，突出孤独和焦虑氛围\"},{\"tag_name\":\"情绪基调\",\"tag_value\":\"焦虑、痛苦、挫败感，氛围紧张\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高清图像，细节清晰，真实感强，面部表情和动作细节突出\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/08/002355_91b4dd3f712247ac8d9992f22b0dbbae.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','37d3d6a3d5424de28175c1d7b835e46f',NULL,NULL,NULL,'2026-09-08 00:22:52.913','2026-09-08 00:22:53.149','2026-09-08 00:23:58.532','2026-09-08 00:23:58.532');
INSERT INTO `attempts` VALUES ('f22a42c3-8229-413a-b4b3-427263ab5a20','7271d4a0-2bdd-4b34-909a-4dc0817dbd89',3,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"把人物[人物.jpg]做成[样例.png]的风格的3D卡通图,人物上半身要全部展示出,展示出正面视角,方便后续建模,衣服需要换成格子衬衫\",\"references\":[\"样例.png\",\"人物.jpg\"],\"tags_prompt\":[{\"tag_name\":\"主体类型\",\"tag_value\":\"人物\"},{\"tag_name\":\"主体数量\",\"tag_value\":\"单人\"},{\"tag_name\":\"外观特征\",\"tag_value\":\"人物上半身全部展示，无遮挡\"},{\"tag_name\":\"服饰配件\",\"tag_value\":\"穿着格子衬衫\"},{\"tag_name\":\"构图方式\",\"tag_value\":\"9宫格布局，每个格子展示人物不同角度\"},{\"tag_name\":\"景别范围\",\"tag_value\":\"上半身展示，半身景\"},{\"tag_name\":\"拍摄视角\",\"tag_value\":\"多视角，包括正面、侧面、背面、斜角等，用于建模参考\"},{\"tag_name\":\"整体风格\",\"tag_value\":\"3D卡通风格，参考样例.png的艺术风格\"},{\"tag_name\":\"媒介形式\",\"tag_value\":\"3D卡通渲染\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"人物结构清晰，细节丰富，适合后续3D建模\"},{\"tag_name\":\"输出质量\",\"tag_value\":\"高质量图像，色彩鲜明，线条平滑\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/07/210900_6189ec96e6014113a2975b4167ec9fdc.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','a00a065be53e4904b6265a3130179d08',NULL,NULL,NULL,'2026-09-07 21:08:12.648','2026-09-07 21:08:12.865','2026-09-07 21:10:17.779','2026-09-07 21:10:17.780');
INSERT INTO `attempts` VALUES ('f3a87953-ce09-41a1-9ab5-f0abdd074c58','f924e8c4-b4ac-41bc-93c4-3642791d5325',4,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"以这张夜晚庭院灯笼照片为基础优化,不改变主体位置和纵向构图。保留中式木栅栏、树干与两盏暖黄色灯笼,强化静谧、温暖、略带孤独感的电影夜景氛围；加入轻薄夜雾、潮湿地面的微弱反光、少量细雨或空气微尘,让灯光自然扩散。整体采用低饱和暖棕与墨黑色调,暗部有细节\\n画面干净克制,去除底部水印和文字。\",\"references\":[\"路灯.jpg\"],\"tags_prompt\":[{\"tag_name\":\"构图方式\",\"tag_value\":\"保留夜晚庭院木栅栏、树干与双灯笼路灯的纵向构图，灯笼作为视觉焦点，画面更干净有层次\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"深邃暗部，暖金色灯光柔和扩散，细微光晕与薄雾，明暗对比克制，营造安静的夜游感\"},{\"tag_name\":\"环境动态\",\"tag_value\":\"加入若隐若现的树叶、潮湿石板路反光、少量漂浮微尘或细雨，远处保留朦胧灯火\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"电影感夜景摄影，低饱和暖棕与墨黑色调，细腻暗部层次，自然胶片颗粒，高级且真实\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"去除底部水印与无关文字，避免过曝灯泡、杂乱背景、过度 HDR、塑料感和不自然锐化\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/03/095636_1b6a387f264246b48895f72de07bcd57.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','dfcad7a39a784610bb533346530db369',NULL,NULL,NULL,'2026-09-03 09:56:08.484','2026-09-03 09:56:09.048','2026-09-03 09:56:38.549','2026-09-03 10:01:24.084');
INSERT INTO `attempts` VALUES ('fc8e5a13-3286-44fd-873c-4ca816439892','f924e8c4-b4ac-41bc-93c4-3642791d5325',2,'succeeded','{\"system_prompt\":\"你是一个专业的图片生成和图片PS大师，请根据用户描述和参考图生成高质量图片，准确理解主体、构图、风格、光线与色彩；不要添加用户未要求的文字、水印或标识，不得添加任何额外的内容。\",\"user_prompt\":\"建议保留原图的暖光与中式庭院结构,把氛围往“雨后静谧电影夜景”推\",\"references\":[\"路灯.jpg\"],\"tags_prompt\":[{\"tag_name\":\"构图方式\",\"tag_value\":\"保留夜晚庭院木栅栏、树干与双灯笼路灯的纵向构图，灯笼作为视觉焦点，画面更干净有层次\"},{\"tag_name\":\"光线质感\",\"tag_value\":\"深邃暗部，暖金色灯光柔和扩散，细微光晕与薄雾，明暗对比克制，营造安静的夜游感\"},{\"tag_name\":\"环境动态\",\"tag_value\":\"加入若隐若现的树叶、潮湿石板路反光、少量漂浮微尘或细雨，远处保留朦胧灯火\"},{\"tag_name\":\"渲染方式\",\"tag_value\":\"电影感夜景摄影，低饱和暖棕与墨黑色调，细腻暗部层次，自然胶片颗粒，高级且真实\"},{\"tag_name\":\"细节要求\",\"tag_value\":\"去除底部水印与无关文字，避免过曝灯泡、杂乱背景、过度 HDR、塑料感和不自然锐化  “你的构想”可以写：\"}]}','gpt-image-2','auto','auto','png',1,'image-to-image','[{\"url\": \"https://mind-scribe.oss-cn-guangzhou.aliyuncs.com/generated-images/2026/09/02/212720_56a72b6550bb4dcba6d109d0a9dab6be.png\", \"mimeType\": \"image/png\", \"sortOrder\": 1}]','79eb7004f17848ea9702c9ee17f3ab5b',NULL,NULL,NULL,'2026-09-02 21:26:35.732','2026-09-02 21:26:37.194','2026-09-02 21:27:21.036','2026-09-02 21:49:04.845');
